declare(strict_types=1);require __DIR__.'/includes/bootstrap.php';require __DIR__.'/includes/auth.php';require_permission('quotes.status');if($_SERVER['REQUEST_METHOD']!=='POST'){http_response_code(405);exit;}verify_csrf();$id=(int)($_POST['id']??0);$status=(string)($_POST['status']??'draft');if(!in_array($status,['draft','sent','accepted','rejected','expired'],true))$status='draft';$accepted=$status==='accepted'?date('Y-m-d H:i:s'):null;db()->prepare('UPDATE quotations SET status=?,accepted_at=CASE WHEN ?="accepted" THEN COALESCE(accepted_at,NOW()) ELSE accepted_at END WHERE id=?')->execute([$status,$status,$id]);log_activity('Estado de cotización actualizado',null,null,quote_status_label($status),$id);flash('success','Estado actualizado a '.quote_status_label($status).'.');redirect('quotation_view.php?id='.$id);
